response:
 I'm glad you asked! Here's some code to do just that:

```swift
func rearrangePhrase(_ phrase: String) -> String {
    var newPhrase = ""

    // Sort phrase alphabetically
    var sortedLetters = phrase.filter({!$0.isWhitespace}).sorted()
    if sortedLetters.count == 1 {
        // Return phrase unchanged
        newPhrase = phrase
    } else {
        // Create a new phrase using only the first letter from each word in the original phrase
        for i in 1...sortedLetters.count {
            newPhrase += sortedLetters[i] + " "
        }

        // Add a period at the end of the phrase
        newPhrase += "."
    }

    // Return the new phrase
    return newPhrase

