response:
 Here’s some sample code:
#include <iostream>
#include <string>
#include <string.h>
#include <algorithm>
using namespace std;
int main() {
    string letters = "hystrio";
    string query = "SELECT * FROM tragedies WHERE name = '" + letters + "'";
    int index = -1;
    int matchFound = 0;
    while ((index = letters.find("h", index + 1)) != -1) {
        index++;
    }
    if (index == -1) {
        // No match!
        cout << "No such tragedy!" << endl;
        return 0;
    }
    index += 1;
    for (int i = index; i <= letters.size(); i++) {
        if (letters[i] == 'h') {
            index = i;
        } else {
            break;
        }
    }
    string name = letters.substr(index, letters.length());
    string summary = letters.substr(0, index);
    cout << "Tragedy is " << name << endl;
    cout << "Summary is " << summary << endl;

